import{_ as t}from"./chunks/phenix-save-manifest.CmJw0V-G.js";import{_ as a,c as s,o as i,ag as r}from"./chunks/framework.DZ_cNctr.js";const o="/docs/screenshots/open-from-url-tab.png",n="/docs/screenshots/slide-index-save.png",k=JSON.parse('{"title":"Remote URLs","description":"Open images, plates and slides from S3, Cloudflare R2, GCS, Azure Blob, Dropbox file links or your own server. Only the parts you look at are fetched, so nothing needs downloading first.","frontmatter":{"title":"Remote URLs","description":"Open images, plates and slides from S3, Cloudflare R2, GCS, Azure Blob, Dropbox file links or your own server. Only the parts you look at are fetched, so nothing needs downloading first."},"headers":[],"relativePath":"guides/remote-urls.md","filePath":"guides/remote-urls.md"}'),l={name:"guides/remote-urls.md"};function d(h,e,p,g,c,u){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="remote-urls" tabindex="-1">Remote URLs <a class="header-anchor" href="#remote-urls" aria-label="Permalink to &quot;Remote URLs&quot;">​</a></h1><p>Open images, plates and slides from a web address. Only the parts you look at are fetched.</p><p>Streaming turns every read into an HTTP range request, so what you serve from matters more than how fast your connection is. <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> covers which storage handles that pattern well, and why an NFS or SMB mount usually does not.</p><h2 id="opening-an-address" tabindex="-1">Opening an Address <a class="header-anchor" href="#opening-an-address" aria-label="Permalink to &quot;Opening an Address&quot;">​</a></h2><ol><li>Click <strong>Open Image</strong> on the landing page.</li><li>Paste the address into the <strong>From URL</strong> tab.</li><li>Click <strong>Load from URL</strong>.</li></ol><img width="1600" height="800" src="'+o+`" alt="The From URL tab of the Open Image window, with an s3:// address pasted in" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>The address can point at:</p><ul><li><p><strong>An OME-Zarr dataset</strong>, as a folder or as one zipped <code>.ozx</code> or <code>.zip</code> file. See <a href="./ome-zarr.html">OME-Zarr</a>.</p></li><li><p><strong>A Zeiss <code>.czi</code> file</strong>, or a zip without compression of a plate saved as one CZI per field. See <a href="./zeiss-czi.html">Zeiss CZI Files</a>.</p></li><li><p><strong>An Opera Phenix or Yokogawa plate</strong>: its measurement folder, its index file, or a zip of the folder. See <a href="./opera-phenix-plates.html">Opera Phenix Plates</a> and <a href="./yokogawa-plates.html">Yokogawa CellVoyager Plates</a>.</p></li><li><p><strong>An OME-TIFF or a slide file</strong>: <code>.ome.tiff</code>, <code>.svs</code>, <code>.ndpi</code>, <code>.scn</code>, Philips <code>.tiff</code>, or the <code>.mrxs</code> file of an MRXS slide.</p></li><li><p><strong>A zip without compression</strong> of an MRXS or DICOM slide.</p></li></ul><p>The viewer reads only what the view needs. It never downloads the whole file or folder first.</p><h2 id="kinds-of-address" tabindex="-1">Kinds of Address <a class="header-anchor" href="#kinds-of-address" aria-label="Permalink to &quot;Kinds of Address&quot;">​</a></h2><ul><li><strong><code>https://</code>.</strong> Any web server or bucket that meets <a href="#what-the-server-needs">What the Server Needs</a>.</li><li><strong><code>s3://</code>.</strong> Paste <code>s3://bucket/path</code> and the viewer reads the bucket&#39;s public https address. A bucket name with a dot works this way in us-east-1. In other regions, paste its regional https address.</li><li><strong><code>gs://</code>.</strong> Paste <code>gs://bucket/path</code> for a public Google Cloud bucket with cross-origin access turned on.</li><li><strong>A private link</strong>, such as a presigned S3 link. It works as it is, query and all. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li><li><strong>A Dropbox file link.</strong> See below.</li></ul><h3 id="dropbox-file-links" tabindex="-1">Dropbox file links <a class="header-anchor" href="#dropbox-file-links" aria-label="Permalink to &quot;Dropbox file links&quot;">​</a></h3><p>Put the file in Dropbox: a zipped OME-Zarr, a <code>.czi</code>, or any other format that is one file, copy its link (<strong>Share</strong>, then <strong>Copy link</strong>), and paste the link as it is. The viewer reads the file from Dropbox&#39;s download address. The address bar and <strong>Copy link</strong> keep the link you pasted.</p><p>Dropbox file links work, but they are not the best way to share data for viewing. Dropbox takes several seconds to answer each read, so opening a large image can take a minute or more. For data you view often, put it in object storage (S3, R2, GCS) or on any web server that supports range requests.</p><p>Dropbox folder links, Google Drive, OneDrive and Proton Drive are not supported. See <a href="#cloud-drives">Cloud Drives</a>.</p><p>Anyone who has the link can open the file, in the viewer or anywhere else.</p><h2 id="what-the-server-needs" tabindex="-1">What the Server Needs <a class="header-anchor" href="#what-the-server-needs" aria-label="Permalink to &quot;What the Server Needs&quot;">​</a></h2><ul><li><strong>CORS.</strong> The server must allow the viewer&#39;s page to read it. For the hosted viewer, that is <code>https://find-nuclei.github.io</code>. Most public OME-Zarr servers, such as the IDR and the BioImage Archive, already do.</li><li><strong>Range requests</strong>, so it can send part of a file. S3, Cloudflare R2, Google Cloud Storage and most web servers do. A one-file format and every zip need them. If a server sends the whole file instead, the viewer stops and says so. Download the file and open it from your disk.</li></ul><p>A CORS rule for an S3 bucket:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;AllowedOrigins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://find-nuclei.github.io&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;AllowedMethods&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HEAD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;AllowedHeaders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ExposeHeaders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Content-Length&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Content-Range&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ETag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;MaxAgeSeconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre></div><p><code>Content-Range</code> must be exposed: without it the browser hides the size of a file read in parts.</p><h2 id="publishing-a-slide-or-a-plate" tabindex="-1">Publishing a Slide or a Plate <a class="header-anchor" href="#publishing-a-slide-or-a-plate" aria-label="Permalink to &quot;Publishing a Slide or a Plate&quot;">​</a></h2><p>Showing a whole slide, an Opera Phenix plate or a CellVoyager plate with a paper, a figure or a blog post? Publish a small file next to it, and your readers see it at once. The image files stay where they are. OME-Zarr needs no such file: its layout is a few small files, and every piece of the image has its own address.</p><h3 id="slide-index" tabindex="-1">Slide Index <a class="header-anchor" href="#slide-index" aria-label="Permalink to &quot;Slide Index&quot;">​</a></h3><p><strong>For whole-slide and TIFF files:</strong> Aperio SVS, Hamamatsu NDPI, Philips TIFF, Leica SCN, Akoya QPTIFF and OME-TIFF.</p><p>A slide far away opens slowly the first time. Before the first picture, the viewer reads the file&#39;s layout, piece after piece, and every piece travels there and back. The same slide opens again in under a second, because the viewer keeps that layout in your browser. A slide index gives every reader that speed on the first open.</p><ol><li>Open the slide by its address.</li><li>Click <strong>Info</strong>, the (i) button in the toolbar, then <strong>Save slide index</strong>. The viewer reads the rest of the slide&#39;s layout and saves <code>&lt;slide&gt;.slide-index.json</code>: a few megabytes for a slide of several gigabytes.</li><li>Host the file on a server that allows CORS, and share its address instead of the slide&#39;s: <code>https://find-nuclei.github.io/?url=&lt;index URL&gt;</code>. The viewer opens the slide.</li></ol><p><img width="2880" height="1800" src="`+n+'" alt="The Image Information dialog for the CAMELYON16 slide tumor_001.tif: 97792 by 221184 pixels, uint8, 0.2431 µm pixels, 3 channels, 10 resolutions, stored remotely, Format reading Philips TIFF file, with the Save slide index button at the bottom" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><ul><li><strong>It follows the slide&#39;s version.</strong> The index records the slide&#39;s ETag and date. If the slide changes, the viewer passes the index over and reads the slide as usual.</li><li><strong>It carries the colour profile.</strong> When the viewer has the slide&#39;s large colour profile, the index holds it too, so the slide opens in true colour with no download.</li><li><strong>The format</strong> is a published JSON Schema, so any tool can write one: <a href="https://find-nuclei.github.io/schemas/slide-index/v1.json" target="_blank" rel="noreferrer">slide-index v1</a>.</li></ul><h3 id="plate-manifest" tabindex="-1">Plate Manifest <a class="header-anchor" href="#plate-manifest" aria-label="Permalink to &quot;Plate Manifest&quot;">​</a></h3><p><strong>For Opera Phenix and Yokogawa CellVoyager plates.</strong> An OME-Zarr plate needs no manifest.</p><p>These plates open from the instrument&#39;s index, which on a large plate takes a minute to read. A published manifest opens the plate without reading its index.</p><ol><li>Open the plate by its address.</li><li>Click <strong>Info</strong>, then <strong>Save plate manifest</strong>. The viewer first reads the whole index, then saves <code>&lt;plate&gt;.plate-manifest.json</code>.</li><li>Host the file next to your page, on any web server or on GitHub, and open it by its address in <strong>From URL</strong>. A link to the viewer works too: <code>https://find-nuclei.github.io/?url=&lt;manifest URL&gt;</code>.</li></ol><p><img width="2880" height="1800" src="'+t+'" alt="The Image Information dialog for plate BR00116991, series A/1/0: 1080 by 1080 pixels, uint16, 0.5980 µm pixels, 8 channels, 1 resolution, stored remotely at an s3:// address in the Cell Painting Gallery, with the Save plate manifest button at the bottom" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><ul><li><strong>The images stay where they are.</strong> The manifest points at them by their full address, and their bucket must let browsers read it, as for any plate on the web.</li><li><strong>A manifest saved from a folder on disk</strong> names no images folder. Put it in the <code>Images/</code> folder next to the TIFFs, then open its address. A manifest file does not open from disk; open the folder instead.</li><li><strong>The format</strong> is a published JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">plate-manifest v1</a>.</li></ul><h2 id="cloud-drives" tabindex="-1">Cloud Drives <a class="header-anchor" href="#cloud-drives" aria-label="Permalink to &quot;Cloud Drives&quot;">​</a></h2><p>Dropbox folder links, Google Drive, OneDrive and Proton Drive do not open. They share a web page, not the files inside, and the viewer has to read the files one by one. Proton Drive is also end-to-end encrypted, so its servers cannot hand out readable files at all.</p><p>What works instead:</p><ul><li><strong>Share one file from Dropbox.</strong> Zip an OME-Zarr dataset into one <code>.ozx</code> file, or share a single-file format as it is. See <a href="#dropbox-file-links">Dropbox file links</a>.</li><li><strong>Open it from your disk.</strong> Download it, then open the file (any browser) or the folder (Chrome or Edge). See <a href="./local-files.html">Local Files</a>.</li><li><strong>Put it on object storage with CORS enabled</strong>, such as S3, Cloudflare R2 or Google Cloud Storage, and open its URL.</li><li><strong>Serve it from your own server.</strong> The <a href="./data-server.html">Data Server guide</a> covers it.</li></ul><h2 id="public-data-to-try" tabindex="-1">Public Data to Try <a class="header-anchor" href="#public-data-to-try" aria-label="Permalink to &quot;Public Data to Try&quot;">​</a></h2><p>These repositories serve their files so the viewer opens them by address. Nothing is downloaded. Each link opens one example.</p><table tabindex="0"><thead><tr><th>Repository</th><th>What opens</th><th>Example</th></tr></thead><tbody><tr><td><a href="https://portal.gdc.cancer.gov/" target="_blank" rel="noreferrer">Genomic Data Commons</a></td><td>Open TCGA slides (Aperio SVS), by <code>https://api.gdc.cancer.gov/data/&lt;file id&gt;</code></td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fapi.gdc.cancer.gov%2Fdata%2F18081e12-b7d5-43b4-ab26-7574b94b98f0" target="_blank" rel="noreferrer">TCGA-05-4245, lung adenocarcinoma</a></td></tr><tr><td><a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource</a></td><td>OME-Zarr images and plates, in 2D and 3D</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0079A%2Fidr0079_images.zarr" target="_blank" rel="noreferrer">Zebrafish lateral line, idr0079</a></td></tr><tr><td><a href="https://www.ebi.ac.uk/bioimage-archive/" target="_blank" rel="noreferrer">BioImage Archive</a></td><td>Files as the authors uploaded them, such as CZI, and its OME-Zarr images</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fftp.ebi.ac.uk%2Fpub%2Fdatabases%2Fbiostudies%2FS-BIAD%2F045%2FS-BIAD4045%2FFiles%2FBODIPY2_DFO_rep1.czi" target="_blank" rel="noreferrer">Confocal CZI, S-BIAD4045</a>, <a href="https://find-nuclei.github.io/?url=https%3A%2F%2Flivingobjects.ebi.ac.uk%2Fbioimaging-integrator-data%2FS-BIAD2339%2F1b738f80-d062-4d74-a97f-20ca241d0ee5%2F2c1e0ae0-5d45-4f6a-b89f-987cc3c24024.ome.zarr" target="_blank" rel="noreferrer">Xenium DAPI image, S-BIAD2339</a></td></tr><tr><td><a href="https://registry.opendata.aws/cellpainting-gallery/" target="_blank" rel="noreferrer">Cell Painting Gallery</a></td><td>Opera Phenix and Yokogawa CellVoyager plates, from their folder</td><td><a href="https://find-nuclei.github.io/?url=s3://cellpainting-gallery/cpg0016-jump/source_2/images/20210607_Batch_2/images/1053601756/" target="_blank" rel="noreferrer">CellVoyager plate 1053601756</a></td></tr><tr><td><a href="https://registry.opendata.aws/camelyon/" target="_blank" rel="noreferrer">CAMELYON16 on AWS Open Data</a></td><td>Lymph node slides, with the tumour outlines in ASAP XML</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fcamelyon-dataset.s3.amazonaws.com%2FCAMELYON16%2Fimages%2Ftumor_001.tif&amp;ann=https%3A%2F%2Fcamelyon-dataset.s3.amazonaws.com%2FCAMELYON16%2Fannotations%2Ftumor_001.xml" target="_blank" rel="noreferrer">tumor_001 with its outlines</a></td></tr><tr><td><a href="https://zenodo.org/" target="_blank" rel="noreferrer">Zenodo</a></td><td>Any file the viewer reads, by its link that ends in <code>/content</code></td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F7015307%2Ffiles%2FW96_B2%2BB4_S%3D2_T%3D1%3DZ%3D1_C%3D1_Tile%3D5x9.czi%2Fcontent" target="_blank" rel="noreferrer">CZI test plate, record 7015307</a></td></tr></tbody></table><p>Some servers only send whole files. The <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/" target="_blank" rel="noreferrer">OpenSlide test data</a> is one: download a slide, then drop it on the viewer.</p><p>Each format&#39;s guide lists public files that open here. <a href="./ome-zarr.html#public-data-to-try">OME-Zarr</a> points at the Image Data Resource, and <a href="./zeiss-czi.html#public-czi-files-to-try">Zeiss CZI Files</a> at public CZI files. Or click <strong>Open Example</strong> on the landing page for datasets known to work well.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./local-files.html">Local Files</a>: the same formats from your disk</li><li><a href="./authenticated-sources.html">Private Images and Slides</a>: a private link or a token</li><li><a href="./data-server.html">Data Server</a>: serve a folder from your own machine</li></ul>',46)])])}const b=a(l,[["render",d]]);export{k as __pageData,b as default};
